def shortest_path(graph, source, target):
    # Initialize the shortest distance to infinity and the previous node to None
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize the previous node to None
    previous = {node: None for node in graph}

    # Priority queue to keep track of nodes to visit, initialized with the source node
    from heapq import heappush, heappop
    queue = [(0, source)]

    while queue:
        # Extract the node with the smallest distance
        current_distance, current_node = heappop(queue)

        # If we reached the target node, reconstruct the path
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = previous[current_node]
            path.reverse()
            return (current_distance, path)

        # Explore the neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If a shorter path is found, update the distance and previous node
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                # Add the neighbor to the queue with the shortest distance
                heappush(queue, (distance, neighbor))

    # If the target node is unreachable, return (float('inf'), None)
    return (float('inf'), None)
