def shortest_path(graph, source, target):
    import heapq

    def dijkstra(graph, source):
        # Priority queue to hold (cost, node) pairs
        queue = [(0, source)]
        # Dictionary to keep track of the shortest distance to each node
        dist = {node: float('infinity') for node in graph}
        dist[source] = 0

        while queue:
            current_cost, node = heapq.heappop(queue)

            # If we found a node with a shorter path, update the distance
            if current_cost < dist[node]:
                continue

            # Explore neighbors
            for neighbor, weight in graph[node]:
                distance = current_cost + weight

                # Only consider this path if it's better
                if distance < dist[neighbor]:
                    dist[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

        return dist

    shortest_distance = dijkstra(graph, source)
    if shortest_distance[target] == float('infinity'):
        return float("inf"), None
    else:
        path = [target]
        while target in graph:
            target = min(graph[target], key=lambda x: (shortest_distance[x], x))
        path.reverse()
        return shortest_distance[target], path

