from collections import defaultdict
import heapq

def shortest_path(graph, source, target):
    # If the target is one of the nodes in the graph, we start the search
    if target in graph:
        # Priority queue to store the nodes to be explored, each element is a tuple (distance, node)
        queue = [(0, source)]
        # Dictionary to keep track of the shortest distance to each node
        distances = {node: float('inf') for node in graph}
        # Dictionary to keep track of the shortest path to each node
        shortest_paths = {node: None for node in graph}
        distances[source] = 0

        while queue:
            current_distance, current_node = heapq.heappop(queue)

            if current_node == target:
                # Reconstruct the shortest path from source to target
                path = []
                while current_node is not None:
                    path.append(current_node)
                    current_node = shortest_paths[current_node]
                path.reverse()
                return (current_distance, path)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    shortest_paths[neighbor] = current_node
                    heapq.heappush(queue, (distance, neighbor))

        # If we reach here, it means the target is unreachable
        return (float('inf'), None)
    else:
        # If the target is not in the graph, the path is unreachable
        return (float('inf'), None)

# Example usage
graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('A', 1), ('C', 2), ('D', 5)],
    'C': [('A', 4), ('B', 2), ('D', 1)],
    'D': [('B', 5), ('C', 1)]
}

source_node = 'A'
target_node = 'D'
print(shortest_path(graph, source_node, target_node))
